import{_ as e,o as s,c as t,ag as i}from"./chunks/framework.OsDJF_Ea.js";const u=JSON.parse('{"title":"AI 슬래시 명령어","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/ai-commands.md","filePath":"02-user-guide/ai-commands.md","lastUpdated":1776160579000}'),o={name:"02-user-guide/ai-commands.md"};function n(l,a,d,r,c,p){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="ai-슬래시-명령어" tabindex="-1">AI 슬래시 명령어 <a class="header-anchor" href="#ai-슬래시-명령어" aria-label="Permalink to &quot;AI 슬래시 명령어&quot;">​</a></h1><p>Workhub에서는 AI를 활용한 슬래시 명령어로 메시지 요약, 회의록 정리, 번역 등을 간편하게 처리할 수 있습니다.</p><hr><h2 id="시작하기" tabindex="-1">시작하기 <a class="header-anchor" href="#시작하기" aria-label="Permalink to &quot;시작하기&quot;">​</a></h2><h3 id="ai-키-설정" tabindex="-1">AI 키 설정 <a class="header-anchor" href="#ai-키-설정" aria-label="Permalink to &quot;AI 키 설정&quot;">​</a></h3><p>AI 명령어를 사용하려면 먼저 개인 AI API 키를 설정해야 합니다.</p><ol><li>왼쪽 사이드바에서 <strong>AI 설정</strong>을 클릭합니다</li><li><strong>Gemini API 키</strong>를 입력합니다</li><li>모델을 선택합니다 (기본: <code>gemini-2.5-flash</code>)</li><li><strong>저장</strong>을 클릭합니다</li></ol><div class="tip custom-block"><p class="custom-block-title">무료 쿼터</p><p>Google Gemini는 무료 사용량을 제공합니다. AI 설정 페이지에서 현재 무료 쿼터 현황을 확인할 수 있습니다.</p></div><hr><h2 id="사용-가능한-명령어" tabindex="-1">사용 가능한 명령어 <a class="header-anchor" href="#사용-가능한-명령어" aria-label="Permalink to &quot;사용 가능한 명령어&quot;">​</a></h2><p>채널이나 토픽의 메시지 입력창에서 <code>/</code>를 입력하면 AI 명령어 목록이 표시됩니다.</p><h3 id="요약-—-메시지-요약" tabindex="-1">/요약 — 메시지 요약 <a class="header-anchor" href="#요약-—-메시지-요약" aria-label="Permalink to &quot;/요약 — 메시지 요약&quot;">​</a></h3><p>최근 메시지를 AI가 요약하여 DM으로 전달합니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/요약          ← 최근 20개 메시지 요약</span></span>
<span class="line"><span>/요약 50       ← 최근 50개 메시지 요약</span></span></code></pre></div><p><strong>결과 수신:</strong> 봇이 DM으로 요약 결과를 보내줍니다.</p><h3 id="회의록-—-회의록-정리" tabindex="-1">/회의록 — 회의록 정리 <a class="header-anchor" href="#회의록-—-회의록-정리" aria-label="Permalink to &quot;/회의록 — 회의록 정리&quot;">​</a></h3><p>최근 대화를 회의록 형식으로 정리하여 DM으로 전달합니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/회의록        ← 최근 30개 메시지로 회의록 생성</span></span>
<span class="line"><span>/회의록 100    ← 최근 100개 메시지로 회의록 생성</span></span></code></pre></div><p><strong>포함 내용:</strong></p><ul><li>참석자</li><li>주요 논의 사항</li><li>결정 사항</li><li>액션 아이템</li></ul><h3 id="번역-—-텍스트-번역" tabindex="-1">/번역 — 텍스트 번역 <a class="header-anchor" href="#번역-—-텍스트-번역" aria-label="Permalink to &quot;/번역 — 텍스트 번역&quot;">​</a></h3><p>입력한 텍스트를 번역합니다. 결과는 입력창 상단에 바로 표시됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/번역 Hello, how are you?        ← 한국어로 번역</span></span>
<span class="line"><span>/번역 en 안녕하세요               ← 영어로 번역</span></span>
<span class="line"><span>/번역 ja 오늘 회의 10시입니다     ← 일본어로 번역</span></span></code></pre></div><p><strong>지원 언어:</strong> 한국어, 영어(<code>en</code>), 일본어(<code>ja</code>), 중국어(<code>zh</code>) 등</p><h3 id="도움말-—-명령어-안내" tabindex="-1">/도움말 — 명령어 안내 <a class="header-anchor" href="#도움말-—-명령어-안내" aria-label="Permalink to &quot;/도움말 — 명령어 안내&quot;">​</a></h3><p>사용 가능한 모든 슬래시 명령어 목록을 확인합니다. 입력창 상단에 바로 표시됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/도움말</span></span></code></pre></div><hr><h2 id="ai-명령어-사용-팁" tabindex="-1">AI 명령어 사용 팁 <a class="header-anchor" href="#ai-명령어-사용-팁" aria-label="Permalink to &quot;AI 명령어 사용 팁&quot;">​</a></h2><h3 id="결과-수신-방식" tabindex="-1">결과 수신 방식 <a class="header-anchor" href="#결과-수신-방식" aria-label="Permalink to &quot;결과 수신 방식&quot;">​</a></h3><table tabindex="0"><thead><tr><th>명령어</th><th>결과 위치</th></tr></thead><tbody><tr><td><code>/요약</code>, <code>/회의록</code></td><td><strong>DM</strong>으로 전달 (봇 DM 확인)</td></tr><tr><td><code>/번역</code>, <code>/도움말</code></td><td><strong>입력창 상단</strong>에 바로 표시</td></tr></tbody></table><h3 id="토픽에서-사용하기" tabindex="-1">토픽에서 사용하기 <a class="header-anchor" href="#토픽에서-사용하기" aria-label="Permalink to &quot;토픽에서 사용하기&quot;">​</a></h3><p>프로젝트 토픽에서 AI 명령어를 사용하면, <strong>해당 토픽의 메시지</strong>만 대상으로 처리됩니다. 예를 들어 디자인 토픽에서 <code>/요약</code>을 실행하면 디자인 관련 대화만 요약합니다.</p><div class="warning custom-block"><p class="custom-block-title">주의사항</p><ul><li>AI API 키가 설정되지 않으면 명령어 실행 시 안내 메시지가 표시됩니다</li><li>요약/회의록은 처리에 수 초가 걸릴 수 있습니다</li><li>결과는 본인에게만 DM으로 전달되며, 다른 사람에게는 보이지 않습니다</li></ul></div>`,34)])])}const b=e(o,[["render",n]]);export{u as __pageData,b as default};
